import base64
import json
import os
from dataclasses import dataclass
from typing import Any, Dict, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class EnvelopeCiphertext:
    encrypted_data_key: str
    iv: str
    ciphertext: str
    key_id: str
    algorithm: str = "AES-256-GCM"
    kms_provider: str = "aws-kms"

    def to_dict(self) -> Dict[str, str]:
        return {
            "kms_provider": self.kms_provider,
            "key_id": self.key_id,
            "algorithm": self.algorithm,
            "encrypted_data_key": self.encrypted_data_key,
            "iv": self.iv,
            "ciphertext": self.ciphertext,
        }

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> "EnvelopeCiphertext":
        return EnvelopeCiphertext(
            encrypted_data_key=data["encrypted_data_key"],
            iv=data["iv"],
            ciphertext=data["ciphertext"],
            key_id=data["key_id"],
            algorithm=data.get("algorithm", "AES-256-GCM"),
            kms_provider=data.get("kms_provider", "aws-kms"),
        )


def _b64encode(raw: bytes) -> str:
    return base64.b64encode(raw).decode("utf-8")


def _b64decode(text: str) -> bytes:
    return base64.b64decode(text.encode("utf-8"))


def _load_kms_client(region_name: Optional[str] = None):
    return boto3.client("kms", region_name=region_name)


def _ensure_bytes(data: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(data, bytes):
        return data
    if isinstance(data, bytearray):
        return bytes(data)
    if isinstance(data, str):
        return data.encode("utf-8")
    raise TypeError("plaintext/ciphertext must be str, bytes, or bytearray")


def encrypt(plaintext: Union[str, bytes, bytearray], key_id: str, region_name: Optional[str] = None) -> Dict[str, str]:
    """
    Envelope encrypts data using AWS KMS to generate a data key, then encrypts
    the plaintext locally with AES-256-GCM.

    Returns a JSON-serializable dictionary containing:
      - encrypted_data_key: base64(KMS-wrapped data key)
      - iv: base64(12-byte AES-GCM nonce)
      - ciphertext: base64(AES-GCM ciphertext + tag)
      - key_id: KMS key ID/ARN used
    """
    try:
        kms = _load_kms_client(region_name=region_name)
        data_key_resp = kms.generate_data_key(KeyId=key_id, KeySpec="AES_256")
        plaintext_data_key = data_key_resp["Plaintext"]
        encrypted_data_key = data_key_resp["CiphertextBlob"]

        from cryptography.hazmat.primitives.ciphers.aead import AESGCM

        aesgcm = AESGCM(plaintext_data_key)
        iv = os.urandom(12)
        plaintext_bytes = _ensure_bytes(plaintext)
        ciphertext = aesgcm.encrypt(iv, plaintext_bytes, None)

        result = EnvelopeCiphertext(
            encrypted_data_key=_b64encode(encrypted_data_key),
            iv=_b64encode(iv),
            ciphertext=_b64encode(ciphertext),
            key_id=key_id,
        )
        return result.to_dict()
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"AWS KMS envelope encryption failed: {e}") from e
    except ImportError as e:
        raise RuntimeError(
            "Missing dependency for local data encryption. Install 'cryptography'."
        ) from e


def decrypt(envelope: Union[Dict[str, Any], str], region_name: Optional[str] = None) -> bytes:
    """
    Decrypts an envelope produced by encrypt().
    Accepts either a dict or a JSON string.
    Returns the original plaintext bytes.
    """
    try:
        if isinstance(envelope, str):
            envelope_dict = json.loads(envelope)
        elif isinstance(envelope, dict):
            envelope_dict = envelope
        else:
            raise TypeError("envelope must be a dict or JSON string")

        enc = EnvelopeCiphertext.from_dict(envelope_dict)

        kms = _load_kms_client(region_name=region_name)
        data_key_resp = kms.decrypt(CiphertextBlob=_b64decode(enc.encrypted_data_key))
        plaintext_data_key = data_key_resp["Plaintext"]

        from cryptography.hazmat.primitives.ciphers.aead import AESGCM

        aesgcm = AESGCM(plaintext_data_key)
        iv = _b64decode(enc.iv)
        ciphertext = _b64decode(enc.ciphertext)
        plaintext = aesgcm.decrypt(iv, ciphertext, None)
        return plaintext
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"AWS KMS envelope decryption failed: {e}") from e
    except ImportError as e:
        raise RuntimeError(
            "Missing dependency for local data decryption. Install 'cryptography'."
        ) from e


def encrypt_json(payload: Any, key_id: str, region_name: Optional[str] = None) -> str:
    """
    Convenience helper: JSON-serialize payload, then envelope-encrypt it.
    Returns a JSON string containing the envelope.
    """
    plaintext = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    return json.dumps(encrypt(plaintext, key_id=key_id, region_name=region_name))


def decrypt_json(envelope: Union[Dict[str, Any], str], region_name: Optional[str] = None) -> Any:
    """
    Convenience helper: decrypt envelope, then JSON-deserialize the plaintext.
    """
    plaintext = decrypt(envelope, region_name=region_name)
    return json.loads(plaintext.decode("utf-8"))
